CREATE VIEW india_dw.air_quality_enriched AS
 SELECT f.measurement_id,
    f.city_id,
    f.date,
    f.aqi_id,
    f.pm25,
    f.pm10,
    f.no_value,
    f.no2,
    f.nox,
    f.nh3,
    f.co,
    f.so2,
    f.o3,
    f.aqi,
    f.temperature_2m_mean,
    f.precipitation_sum,
    f.wind_speed_10m_max,
    f.grid_latitude,
    f.grid_longitude,
    f.weather_model,
    f.run_id,
    c.city_name,
    c.latitude,
    c.longitude,
    c.source_url,
    a.aqi_bucket,
    d.year,
    d.month,
    d.day,
    d.quarter,
    d.day_of_week
   FROM (((india_dw.fact_air_quality f
     JOIN india_dw.dim_city c USING (city_id))
     JOIN india_dw.dim_date d USING (date))
     JOIN india_dw.dim_aqi a USING (aqi_id));


